fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

sealed class Outcome170 {
    data class Success(val payload: String) : Outcome170()
    data object Failure : Outcome170()
}

fun describe170(outcome: Outcome170): String = when (outcome) {
    is Outcome170.Success -> outcome.payload
    Outcome170.Failure -> "failed"
}
fun <T, R> List<T>.mapChecked171(transform: (T) -> R): List<R> {
    val result = mutableListOf<R>()
    for (item in this) {
        result.add(transform(item))
    }
    return result
}
